import{r as s}from"./index-B2lI7iTC.js";const y="zl_daily_flow",g="zl_daily_streak",c=()=>{const e=new Date;return`${e.getFullYear()}-${String(e.getMonth()+1).padStart(2,"0")}-${String(e.getDate()).padStart(2,"0")}`};function A(){try{const o=localStorage.getItem(y);if(o){const t=JSON.parse(o);return t.today.date!==c()&&((t.today.checkIn||t.today.doseCompletedId||t.today.reflection)&&(t.history=[t.today,...t.history].slice(0,90)),t.today=h(),p(t)),t}}catch{}const e={today:h(),history:[]};return p(e),e}function p(e){try{localStorage.setItem(y,JSON.stringify(e))}catch{}}function h(){return{date:c(),checkIn:null,doseCompletedId:null,reflection:null,xpEarned:0}}function P(){try{const e=localStorage.getItem(g);if(e)return JSON.parse(e)}catch{}return{currentStreak:0,lastFullFlowDate:null}}function C(e){try{localStorage.setItem(g,JSON.stringify(e))}catch{}}function R(e){const o=new Date(e+"T12:00:00"),t=new Date;return t.setDate(t.getDate()-1),o.getFullYear()===t.getFullYear()&&o.getMonth()===t.getMonth()&&o.getDate()===t.getDate()}function L(){const[e,o]=s.useState(A),[t,E]=s.useState(P);s.useEffect(()=>{p(e)},[e]),s.useEffect(()=>{C(t)},[t]);const f=s.useCallback(r=>{o(a=>{const n={...a.today,checkIn:r},i=n.xpEarned+5;return{...a,today:{...n,xpEarned:i}}})},[]),b=s.useCallback(r=>{o(a=>{if(a.today.doseCompletedId)return a;const n=a.today.xpEarned+15;return{...a,today:{...a.today,doseCompletedId:r,xpEarned:n}}})},[]),v=s.useCallback(r=>{o(a=>{const n=a.today.xpEarned+10,i={...a.today,reflection:r,xpEarned:n};return i.checkIn!==null&&i.doseCompletedId!==null&&i.reflection!==null&&E(d=>{const u=d.lastFullFlowDate;let l=d.currentStreak;return u&&(R(u)||u===c())?(l=d.currentStreak||1,u!==c()&&(l+=1)):l=1,{currentStreak:l,lastFullFlowDate:c()}}),{...a,today:i}})},[]),w=s.useCallback(()=>({checkedIn:e.today.checkIn!==null,doseCompleted:e.today.doseCompletedId!==null,reflected:e.today.reflection!==null}),[e.today]),x=s.useCallback(()=>t.currentStreak,[t]),k=s.useCallback(r=>e.today.doseCompletedId===r,[e.today.doseCompletedId]),T=s.useCallback(()=>e.today.xpEarned,[e.today.xpEarned]),S=e.today;return{checkIn:f,completeDailyDose:b,endOfShift:v,getTodayProgress:w,getCurrentStreak:x,isDoseCompleted:k,getTodaysXp:T,todayState:S}}const m=[{id:"dose-001",day:1,title:"The Energy First Rule",titleEs:"La Regla de la Energía Primero",category:"Stopping",content:[{type:"mindset",text:"Before you say a word, your energy speaks. A tired approach gets a tired response. Energy is contagious — bring the fire.",textEs:"Antes de decir una palabra, tu energía habla. Un acercamiento cansado genera una respuesta cansada. La energía es contagiosa — trae el fuego.",highlight:"Your energy is your first word.",highlightEs:"Tu energía es tu primera palabra."},{type:"tip",text:"Take three deep breaths before every approach. Stand tall. Smile like you just heard great news. Your body changes your mind.",textEs:"Toma tres respiraciones profundas antes de cada acercamiento. Ponte derecha. Sonríe como si acabaras de escuchar buenas noticias. Tu cuerpo cambia tu mente."},{type:"script",text:`Internal mantra: "I am the best thing to happen to this person's day."`,textEs:'Mantra interno: "Soy lo mejor que le pasará en el día a esta persona."'}],practicePrompt:"On your next 5 approaches, pay attention only to your energy level. Rate yourself 1-5 after each. What do you notice?",practicePromptEs:"En tus próximos 5 acercamientos, presta atención solo a tu nivel de energía. Califícate del 1 al 5 después de cada uno. ¿Qué notas?",xpReward:15},{id:"dose-002",day:2,title:"The Genuine Compliment",titleEs:"El Cumplido Genuino",category:"Stopping",content:[{type:"mindset",text:'A compliment opens the door. But it must be SPECIFIC and GENUINE. "Nice dress" is weak. "That colour looks amazing on you" is strong.',textEs:'Un cumplido abre la puerta. Pero debe ser ESPECÍFICO y GENUINO. "Lindo vestido" es débil. "Ese color te queda increíble" es fuerte.',highlight:"Specific compliments stop people. Generic ones don't.",highlightEs:"Los cumplidos específicos detienen a la gente. Los genéricos no."},{type:"technique",text:"The DETAIL RULE: Pick one specific detail — a colour, an accessory, a hairstyle, the way they carry themselves. Name it. Own it.",textEs:"La REGLA DEL DETALLE: Elige un detalle específico — un color, un accesorio, un peinado, su forma de caminar. Nombrarlo. Aprópiate de ello."},{type:"script",text:'"Excuse me, I just have to say — that scarf is stunning. The way you tied it, so elegant!"',textEs:'"Disculpe, solo quería decirle — esa bufanda es deslumbrante. La forma en que la anudó, ¡tan elegante!"'}],practicePrompt:'Give 5 specific compliments today. Write down which ones got a smile or a "thank you." What pattern do you see?',practicePromptEs:'Da 5 cumplidos específicos hoy. Anota cuáles provocaron una sonrisa o un "gracias." ¿Qué patrón ves?',xpReward:15},{id:"dose-003",day:3,title:"Eye Contact That Hooks",titleEs:"Contacto Visual Que Engancha",category:"Stopping",content:[{type:"tip",text:"Eye contact is your secret weapon. Most salespeople look at the product. You look at the PERSON. Hold eye contact one second longer than feels comfortable.",textEs:"El contacto visual es tu arma secreta. La mayoría de los vendedores miran el producto. Tú mira a la PERSONA. Mantén el contacto visual un segundo más de lo que te resulta cómodo.",highlight:"One extra second of eye contact builds instant trust.",highlightEs:"Un segundo extra de contacto visual genera confianza instantánea."},{type:"technique",text:"The LOCK-AND-SMILE: Make eye contact, hold it, and let a slow smile spread. Not a grin — a warm, genuine smile that reaches your eyes.",textEs:"El BLOQUEO-Y-SONRISA: Haz contacto visual, mantenlo, y deja que una sonrisa lenta se expanda. No una carcajada — una sonrisa cálida y genuina que llegue a tus ojos."},{type:"script",text:`"Hi there — sorry to stop you, but I just noticed your eyes sparkle and I couldn't walk past. I'm [Name] by the way!"`,textEs:'"Hola — perdón por detenerla, pero noté que sus ojos brillan y no pude pasar de largo. ¡Soy [Nombre], por cierto!"'}],practicePrompt:"Practice the Lock-and-Smile on 5 strangers today. Count how many return the smile. Record the number.",practicePromptEs:"Practica el Bloqueo-y-Sonrisa con 5 desconocidos hoy. Cuenta cuántos devuelven la sonrisa. Registra el número.",xpReward:15},{id:"dose-004",day:4,title:"Positioning & Proximity",titleEs:"Posicionamiento y Proximidad",category:"Stopping",content:[{type:"tip",text:"Where you stand matters as much as what you say. Too close = threat. Too far = ignored. The magic zone is 1.5 to 2 metres. Angle your body slightly sideways — it's less confrontational.",textEs:"Dónde te pares importa tanto como lo que dices. Demasiado cerca = amenaza. Demasiado lejos = ignorado. La zona mágica es de 1.5 a 2 metros. Inclina tu cuerpo ligeramente de lado — es menos confrontacional.",highlight:"Side-on stance = approachable. Front-on = confrontational.",highlightEs:"Postura de lado = accesible. De frente = confrontacional."},{type:"technique",text:"The ARC APPROACH: Don't walk straight at them. Curve in from the side like you're joining a friend. It disarms their defensive reflex.",textEs:"El ACERCAMIENTO EN ARCO: No camines directamente hacia ellos. Curva desde el lado como si te unieras a un amigo. Desarma su reflejo defensivo."},{type:"tip",text:"Mirror their pace. If they're walking fast, use more energy. If they're strolling, slow down your approach. Match, then lead.",textEs:"Refleja su ritmo. Si caminan rápido, usa más energía. Si pasean, reduce la velocidad de tu acercamiento. Empareja, luego lidera."}],practicePrompt:"Try the Arc Approach on 5 people today. Compare your stop rate vs. a straight-on approach. What difference do you notice?",practicePromptEs:"Prueba el Acercamiento en Arco con 5 personas hoy. Compara tu tasa de parada vs. un acercamiento directo. ¿Qué diferencia notas?",xpReward:15},{id:"dose-005",day:5,title:"Rejection Is Data",titleEs:"El Rechazo Es Información",category:"Stopping",content:[{type:"mindset",text:`Every "no" teaches you something. The goal today isn't zero rejection — it's LEARNING from every rejection. What did they say? What was their body language? What can you adjust?`,textEs:'Cada "no" te enseña algo. La meta hoy no es cero rechazos — es APRENDER de cada rechazo. ¿Qué dijeron? ¿Cuál fue su lenguaje corporal? ¿Qué puedes ajustar?',highlight:"Rejection is feedback. Feedback is fuel.",highlightEs:"El rechazo es retroalimentación. La retroalimentación es combustible."},{type:"technique",text:"The AFTER-ACTION REVIEW: After every 10 approaches, ask yourself: What worked? What didn't? What will I try differently? Write it down.",textEs:"La REVISIÓN POST-ACCIÓN: Después de cada 10 acercamientos, pregúntate: ¿Qué funcionó? ¿Qué no? ¿Qué intentaré diferente? Escríbelo."},{type:"mindset",text:"The 80/20 rule: 80% of people will say no. That's normal. Your job is to find the 20% who say yes. Every no gets you closer to a yes.",textEs:"La regla 80/20: El 80% de la gente dirá que no. Es normal. Tu trabajo es encontrar el 20% que dice sí. Cada no te acerca a un sí."}],practicePrompt:"Track your next 10 rejections. Note ONE thing about each (their body language, what they said, time of day). Look for patterns.",practicePromptEs:"Registra tus próximos 10 rechazos. Nota UNA cosa de cada uno (su lenguaje corporal, lo que dijeron, hora del día). Busca patrones.",xpReward:15},{id:"dose-006",day:6,title:"The Connection Bridge",titleEs:"El Puente de Conexión",category:"Stopping",content:[{type:"technique",text:"Stop → Compliment → BRIDGE. The bridge is a question or statement that moves you from stranger to conversational partner. It must feel natural, not forced.",textEs:"Detener → Cumplido → PUENTE. El puente es una pregunta o afirmación que te mueve de desconocido a interlocutor. Debe sentirse natural, no forzado.",highlight:"The bridge turns a stop into a conversation.",highlightEs:"El puente convierte una parada en una conversación."},{type:"script",text:`"...I'm actually working with a Swiss skincare brand today, and we just opened a pop-up down the road. Have you heard of Dead Sea minerals?"`,textEs:'"...de hecho estoy trabajando con una marca suiza de cuidado de la piel hoy, y acabamos de abrir un pop-up aquí cerca. ¿Has oído hablar de los minerales del Mar Muerto?"'},{type:"tip",text:"The best bridges are CURIOSITY-BASED. People can't resist answering a question they're curious about. Make them wonder.",textEs:"Los mejores puentes se basan en la CURIOSIDAD. La gente no puede resistirse a responder una pregunta que les despierta curiosidad. Haz que se pregunten."}],practicePrompt:'Craft 3 different "bridge" questions today. Test each one at least twice. Which one gets the best response?',practicePromptEs:'Crea 3 "puentes" diferentes hoy. Prueba cada uno al menos dos veces. ¿Cuál obtiene la mejor respuesta?',xpReward:15},{id:"dose-007",day:7,title:"Handing Off Like a Pro",titleEs:"Transfiriendo Como una Profesional",category:"Stopping",content:[{type:"technique",text:"The hand-off to your colleague inside is CRITICAL. A sloppy hand-off kills deals. A smooth one seals them. Make your client feel VIP during the transition.",textEs:"La transferencia a tu colega dentro es CRÍTICA. Una transferencia descuidada mata tratos. Una fluida los cierra. Haz que tu cliente se sienta VIP durante la transición.",highlight:"The hand-off is part of the sale, not the end of it.",highlightEs:"La transferencia es parte de la venta, no el final de ella."},{type:"script",text:`"Let me walk you in — my colleague [Name] is going to take amazing care of you. She's our skincare expert and she has a special gift waiting for you today."`,textEs:'"Déjame acompañarte — mi colega [Nombre] te va a cuidar increíblemente. Ella es nuestra experta en cuidado de la piel y tiene un regalo especial esperándote hoy."'},{type:"tip",text:"Always introduce your colleague by name. Always mention their expertise. Always promise something special. This builds anticipation and trust.",textEs:"Siempre presenta a tu colega por nombre. Siempre menciona su experiencia. Siempre promete algo especial. Esto genera anticipación y confianza."}],practicePrompt:"Practice your hand-off script 3 times with a colleague today. Ask for feedback. What felt natural? What felt forced?",practicePromptEs:"Practica tu script de transferencia 3 veces con un colega hoy. Pide retroalimentación. ¿Qué se sintió natural? ¿Qué se sintió forzado?",xpReward:15},{id:"dose-008",day:8,title:"The Syringe Demo That Sells",titleEs:"La Demo de Jeringa Que Vende",category:"Product",content:[{type:"technique",text:"The syringe demo is your WOW moment. Don't rush it. Build suspense. Let them see the transformation happen on their own hand.",textEs:"La demo de jeringa es tu momento WOW. No te apresures. Genera suspense. Deja que vean la transformación en su propia mano.",highlight:"Let them feel it. Feeling = believing.",highlightEs:"Déjalas sentirlo. Sentir = creer."},{type:"script",text:`"Watch this — I'm going to put a tiny drop on the back of your hand. Feel that? It's warm. That's the hyaluronic acid activating, drawing moisture deep into your skin."`,textEs:'"Mira esto — voy a poner una gotita en el dorso de tu mano. ¿Lo sientes? Está caliente. Eso es el ácido hialurónico activándose, atrayendo humedad profundamente en tu piel."'},{type:"tip",text:`After the demo, DON'T talk. Let silence work. Wait for them to say "Wow" or ask a question. The first person to speak loses — and you want them to lose.`,textEs:'Después de la demo, NO hables. Deja que el silencio trabaje. Espera a que digan "Wow" o hagan una pregunta. La primera persona en hablar pierde — y quieres que ellos pierdan.'}],practicePrompt:"Do 5 syringe demos today. Time yourself — aim for 45 seconds of pure silence after application. Count how many times the client breaks the silence first.",practicePromptEs:"Haz 5 demos de jeringa hoy. Cómprate el tiempo — apunta a 45 segundos de silencio puro después de la aplicación. Cuenta cuántas veces el cliente rompe el silencio primero.",xpReward:15},{id:"dose-009",day:9,title:"Peeling Demo Magic",titleEs:"La Magia de la Demo de Peeling",category:"Product",content:[{type:"technique",text:"The peeling demo creates instant visual proof. Dead skin rolling off their hand is visceral. It triggers disgust AND desire — the perfect combo.",textEs:"La demo de peeling crea prueba visual instantánea. La piel muerta saliendo de su mano es visceral. Despierta asco Y deseo — la combinación perfecta.",highlight:"Visual proof beats verbal claims every time.",highlightEs:"La prueba visual supera a las afirmaciones verbales siempre."},{type:"script",text:`"I'm going to show you something incredible. The Peeling separates dead skin you didn't even know you had. Watch — roll it gently, don't rub... see those grey bits? That's years of buildup, gone in seconds."`,textEs:'"Voy a enseñarte algo increíble. El Peeling separa la piel muerta que ni siquiera sabías que tenías. Mira — enróllalo suavemente, no lo frotes... ¿ves esas bolitas grises? Son años de acumulación, fuera en segundos."'},{type:"tip",text:'ALWAYS do the peeling demo on the BACK of their hand, not the palm. The back shows results better and feels more "skincare" than "cleaning."',textEs:'SIEMPRE haz la demo de peeling en el DORSO de la mano, no en la palma. El dorso muestra mejores resultados y se siente más como "cuidado de piel" que como "limpieza."'}],practicePrompt:"Track your peeling-to-sale conversion today. Out of every peeling demo you do, how many lead to a product sale? Aim for 60%+.",practicePromptEs:"Registra tu conversión de peeling-a-venta hoy. De cada demo de peeling que hagas, ¿cuántas llevan a una venta? Apunta al 60%+.",xpReward:15},{id:"dose-010",day:10,title:"Scrub Demo Mastery",titleEs:"Dominio de la Demo de Exfoliante",category:"Product",content:[{type:"technique",text:"The salt scrub is a sensory experience. Use descriptive words that engage touch and smell. Make it luxurious, not clinical.",textEs:"El exfoliante de sal es una experiencia sensorial. Usa palabras descriptivas que enganchen el tacto y el olfato. Hazlo lujoso, no clínico.",highlight:"Words create experience. Choose luxurious language.",highlightEs:"Las palabras crean experiencia. Elige lenguaje lujoso."},{type:"script",text:`"Close your eyes and smell this — Dead Sea salt, lavender, vitamin E. Feel the crystals? They're melting into your skin, releasing minerals that boost circulation. Your skin will feel like silk."`,textEs:'"Cierra los ojos y huele esto — sal del Mar Muerto, lavanda, vitamina E. ¿Sientes los cristales? Se están derritiendo en tu piel, liberando minerales que mejoran la circulación. Tu piel se sentirá como seda."'},{type:"tip",text:"Have them smell BEFORE they see. Scent is the fastest path to emotion. When they smell first, they're already sold before the demo even starts.",textEs:"Haz que huelan ANTES de ver. El aroma es el camino más rápido a la emoción. Cuando huelen primero, ya están vendidas antes de que la demo empiece."}],practicePrompt:'Try the "smell first" approach on 5 clients today. Compare reactions vs. showing first. Record your observations.',practicePromptEs:'Prueba el enfoque "huele primero" con 5 clientes hoy. Compara reacciones vs. mostrar primero. Registra tus observaciones.',xpReward:15},{id:"dose-011",day:11,title:"Nail Kit Demo Secrets",titleEs:"Secretos de la Demo del Kit de Uñas",category:"Product",content:[{type:"technique",text:"The nail kit is a 3-step story: Cut → File → Shine. Each step has its own moment. Don't rush the shine — that's the WOW.",textEs:"El kit de uñas es una historia de 3 pasos: Cortar → Limar → Brillar. Cada paso tiene su propio momento. No te apresures con el brillo — ese es el WOW.",highlight:"The shine step is your closer. Make it dramatic.",highlightEs:"El paso del brillo es tu cerrador. Hazlo dramático."},{type:"script",text:'"Most nail files tear your nails. This one is crystal glass — it seals the edge as it files. And this buffer? 30 seconds and your nails will shine like you just had a salon manicure."',textEs:'"La mayoría de limas de uñas las desgarran. Esta es de cristal — sella el borde mientras lima. ¿Y este pulidor? 30 segundos y tus uñas brillarán como si te hubieras hecho una manicura de salón."'},{type:"tip",text:"Demo on ONE nail only. Let them do the rest themselves. When they feel the difference between the done nail and the undone ones, the sale makes itself.",textEs:"Haz la demo en UNA uña solamente. Deja que hagan el resto ellas mismas. Cuando sientan la diferencia entre la uña hecha y las sin hacer, la venta se hace sola."}],practicePrompt:"Do 3 one-nail demos today. Count how many clients ask to do the rest themselves. That's your closing signal.",practicePromptEs:"Haz 3 demos de una uña hoy. Cuenta cuántas clientes piden hacer el resto ellas mismas. Esa es tu señal de cierre.",xpReward:15},{id:"dose-012",day:12,title:"Price Anchoring That Works",titleEs:"Anclaje de Precio Que Funciona",category:"Product",content:[{type:"technique",text:"Never lead with the price. Anchor HIGH first. Compare your product to luxury alternatives that cost 3x more. Then your price feels like a steal.",textEs:"Nunca empieces con el precio. Ancla ALTO primero. Compara tu producto con alternativas de lujo que cuestan 3 veces más. Entonces tu precio se siente como una ganga.",highlight:"{currency}300 feels cheap the second after you said {currency}500.",highlightEs:"{currency}300 se siente barato justo después de haber dicho {currency}500."},{type:"script",text:`"Across Europe this same treatment goes for {currency}500 — it's the one that works instantly and lasts. Here we're a tax-free shop, so it's {currency}300. That's why we sell out every single day."`,textEs:'"Por toda Europa este mismo tratamiento cuesta {currency}500 — es el que funciona al instante y dura. Aquí estamos libres de impuestos, así que son {currency}300. Por eso se agota todos los días."'},{type:"tip",text:'Use the phrase "investment" not "cost." Say "Your skin is an investment" not "This syringe costs {currency}300." Language shapes perception.',textEs:'Usa la palabra "inversión", no "coste". Di "Tu piel es una inversión", no "Esta jeringa cuesta {currency}300". El lenguaje moldea la percepción.'}],practicePrompt:"Today, always anchor with a luxury comparison before stating your price. Track: does this increase your close rate?",practicePromptEs:"Hoy, siempre ancla con una comparación de lujo antes de decir tu precio. Registra: ¿aumenta esto tu tasa de cierre?",xpReward:15},{id:"dose-013",day:13,title:"Cross-Selling Made Easy",titleEs:"Ventas Cruzadas Facilitadas",category:"Product",content:[{type:"technique",text:"Cross-selling isn't pushy if it's HELPFUL. The key: suggest products that COMPLEMENT what they already want. A Scrub buyer needs the matching Body Butter.",textEs:"La venta cruzada no es agresiva si es ÚTIL. La clave: sugiere productos que COMPLEMENTEN lo que ya quieren. Quien se lleva el Scrub necesita el Body Butter que va con él.",highlight:"Help them complete their routine. Don't just add products.",highlightEs:"Ayúdalas a completar su rutina. No solo agregues productos."},{type:"script",text:`"Since you're taking the Scrub, you'll want the Body Butter too. They're designed to work together — the Scrub lifts the dead skin, the Butter locks the moisture back in. And Buy 1 Get 1 means both of them are {currency}60 — the price of one."`,textEs:'"Como te llevas el Scrub, también vas a querer el Body Butter. Están hechos para funcionar juntos — el Scrub levanta la piel muerta y el Butter le devuelve la hidratación. Y con Compra 1 Lleva 1 los dos te salen {currency}60 — el precio de uno."'},{type:"tip",text:`Bundle pricing is your friend. Always frame the combo as saving money, not spending more. Three products at {currency}120 instead of {currency}180 — say "you save {currency}60", never "it's {currency}60 more."`,textEs:'El precio de paquete es tu aliado. Presenta siempre el combo como ahorro, no como gasto extra. Tres productos por {currency}120 en vez de {currency}180 — di "ahorras {currency}60", nunca "son {currency}60 más".'}],practicePrompt:"Set a cross-sell goal today: for every product sold, suggest ONE complementary item. Track your success rate.",practicePromptEs:"Pon una meta de venta cruzada hoy: por cada producto vendido, sugiere UN artículo complementario. Registra tu tasa de éxito.",xpReward:15},{id:"dose-014",day:14,title:"The Combo Close",titleEs:"El Cierre de Combo",category:"Product",content:[{type:"technique",text:"The 3-product combo is your highest-value sale. Present it as a COMPLETE SYSTEM, not random items. People buy systems, not products.",textEs:"El combo de 3 productos es tu venta de mayor valor. Preséntalo como un SISTEMA COMPLETO, no artículos al azar. La gente compra sistemas, no productos.",highlight:"A system feels complete. Random products feel pushy.",highlightEs:"Un sistema se siente completo. Productos al azar se sienten agresivos."},{type:"script",text:'"I want to set you up with the full system. The Scrub lifts the dead skin, the Body Butter feeds it back, and the Nail Kit finishes your hands. Three products, {currency}120 with Buy 2 Get 1 — five minutes a week, results you can see the first time."',textEs:'"Quiero dejarte el sistema completo. El Scrub levanta la piel muerta, el Body Butter se la devuelve, y el Kit de Uñas remata tus manos. Tres productos, {currency}120 con Compra 2 Lleva 1 — cinco minutos a la semana, resultados que ves desde el primer uso."'},{type:"tip",text:'When presenting the combo, use your hands to show "steps." Finger 1 = Scrub, Finger 2 = Body Butter, Finger 3 = Nail Kit. Visual structure increases perceived value.',textEs:'Al presentar el combo, usa las manos para marcar los "pasos". Dedo 1 = Scrub, Dedo 2 = Body Butter, Dedo 3 = Kit de Uñas. La estructura visual aumenta el valor percibido.'}],practicePrompt:"Aim to present the full combo to 3 people today. Even if they don't buy all 3, track how many buy 2+ items.",practicePromptEs:"Apunta a presentar el combo completo a 3 personas hoy. Incluso si no compran los 3, registra cuántos compran 2+ artículos.",xpReward:15},{id:"dose-015",day:15,title:"Price Too High? Perfect.",titleEs:"¿Precio Demasiado Alto? Perfecto.",category:"Closing",content:[{type:"mindset",text:'"Too expensive" is a GOOD objection. It means they WANT it, they just need help justifying it. Your job: reframe the value, not lower the price.',textEs:'"Demasiado caro" es una BUENA objeción. Significa que LO QUIEREN, solo necesitan ayuda para justificarlo. Tu trabajo: reformular el valor, no bajar el precio.',highlight:'"Too expensive" = "I want it but need permission."',highlightEs:'"Demasiado caro" = "Lo quiero pero necesito permiso."'},{type:"script",text:`"I completely understand. Here's how I think about it: this bottle lasts a full year — 52 treatments for {currency}100. That's under {currency}2 a week, less than one coffee. And unlike coffee, this actually makes you look younger."`,textEs:'"Te entiendo perfectamente. Yo lo veo así: este frasco dura un año entero — 52 tratamientos por {currency}100. Son menos de {currency}2 a la semana, menos que un café. Y a diferencia del café, esto sí te hace ver más joven."'},{type:"technique",text:"The COST-PER-WEEK REFRAME: break any price into what it costs while it lasts. The Peeling at {currency}100 lasts a year — under {currency}2 a week. The Syringe at {currency}300 lasts a year too — under {currency}6 a week. Compare it to something they buy every week. It shrinks the price in their mind.",textEs:"EL REENCUADRE DE COSTE POR SEMANA: divide cualquier precio entre el tiempo que dura. El Peeling a {currency}100 dura un año — menos de {currency}2 a la semana. La Jeringa a {currency}300 también dura un año — menos de {currency}6 a la semana. Compáralo con algo que compren cada semana. Encoge el precio en su cabeza."}],practicePrompt:'When you hear "too expensive" today, use the cost-per-week reframe. Track your conversion rate on this specific objection.',practicePromptEs:'Cuando escuches "demasiado caro" hoy, usa el reencuadre de coste por semana. Registra tu tasa de conversión en esa objeción concreta.',xpReward:20},{id:"dose-016",day:16,title:'The "Need to Think" Kill Shot',titleEs:'El Golpe de Gracia al "Necesito Pensarlo"',category:"Closing",content:[{type:"mindset",text:`"I need to think about it" often means "I'm not convinced yet." Don't let them walk. Find the REAL hesitation and address it head-on.`,textEs:'"Necesito pensarlo" a menudo significa "No estoy convencida todavía." No dejes que se vayan. Encuentra la VERDADERA hesitación y enfréntala directamente.',highlight:'The real objection is hiding behind "I need to think."',highlightEs:'La objeción real se esconde detrás del "necesito pensarlo."'},{type:"script",text:'"Of course! What specifically would you like to think about — is it the product itself, the price, or whether it will work for your skin? I want to make sure I answered all your questions."',textEs:'"¡Por supuesto! ¿Qué te gustaría pensar específicamente — es el producto en sí, el precio, o si funcionará para tu piel? Quiero asegurarme de haber respondido todas tus preguntas."'},{type:"technique",text:"The DIRECT QUESTION: Isolate the objection. Is it price? Product? Timing? Once you know, you can handle it. Until you know, you're guessing.",textEs:"La PREGUNTA DIRECTA: Aísla la objeción. ¿Es el precio? ¿El producto? ¿El momento? Una vez que lo sabes, puedes manejarlo. Hasta que lo sepas, estás adivinando."}],practicePrompt:`Today, when someone says "I'll think about it," ask the direct question above. Record what the REAL objection was.`,practicePromptEs:'Hoy, cuando alguien diga "lo pensaré," haz la pregunta directa de arriba. Registra cuál era la objeción REAL.',xpReward:20},{id:"dose-017",day:17,title:"The Husband Objection",titleEs:"La Objeción del Marido",category:"Closing",content:[{type:"mindset",text:'"I need to ask my husband" can mean two things: genuine need to consult, or a polite excuse. Your job: find out which, and handle accordingly.',textEs:'"Necesito preguntarle a mi marido" puede significar dos cosas: necesidad genuina de consultar, o una excusa educada. Tu trabajo: averiguar cuál, y manejarlo en consecuencia.',highlight:'Never argue with "my husband." Work WITH it.',highlightEs:'Nunca discutas con "mi marido." Trabaja CON ello.'},{type:"script",text:`"That's totally fair! Here's what I suggest: let me give you our card and write down exactly what we discussed. When you talk to him, you can say 'I tried it, I loved it, and it's {currency}100 and the bottle lasts a whole year.' Most husbands just want to know it's a good deal!"`,textEs:`"¡Totalmente justo! Te sugiero: déjame darte nuestra tarjeta y anotar exactamente de qué hablamos. Cuando le hables, puedes decir 'Lo probé, me encantó, y son {currency}100 y el frasco dura un año entero.' ¡La mayoría de los maridos solo quieren saber que es un buen trato!"`},{type:"tip",text:"If she genuinely wants to ask, make it EASY for her to sell it to him. Write down the key points. Give her the words. She becomes YOUR salesperson at home.",textEs:"Si ella genuinamente quiere preguntar, haz que sea FÁCIL venderle a él. Anota los puntos clave. Dale las palabras. Ella se convierte en TU vendedora en casa."}],practicePrompt:"When you hear the husband objection today, use the card technique. Track how many come back or buy on the spot.",practicePromptEs:"Cuando escuches la objeción del marido hoy, usa la técnica de la tarjeta. Registra cuántas vuelven o compran en el momento.",xpReward:20},{id:"dose-018",day:18,title:'The "Just Looking" Redirect',titleEs:'El Desvío del "Solo Miro"',category:"Closing",content:[{type:"mindset",text:`"Just looking" is a reflex, not a real objection. They've been trained to say it. Don't take it personally. Redirect with curiosity or humour.`,textEs:'"Solo miro" es un reflejo, no una objeción real. Han sido entrenadas para decirlo. No lo tomes personal. Redirige con curiosidad o humor.',highlight:'"Just looking" is a habit. Break the pattern.',highlightEs:'"Solo miro" es un hábito. Rompe el patrón.'},{type:"script",text:`"Perfect, looking is free! Actually, since you're just looking, let me show you something cool — have you ever seen the Peeling roll dead skin off your hand in seconds? It's really satisfying to watch."`,textEs:'"Perfecto, ¡mirar es gratis! De hecho, como solo estás mirando, déjame mostrarte algo genial — ¿has visto cómo el Peeling saca la piel muerta de la mano en segundos? Es muy satisfactorio de ver."'},{type:"technique",text:'The AGREE-AND-PIVOT: Never fight "just looking." Agree enthusiastically, then pivot to something intriguing. Curiosity is stronger than resistance.',textEs:'El ACUERDO-Y-GIRO: Nunca luches contra "solo miro." Acepta con entusiasmo, luego gira hacia algo intrigante. La curiosidad es más fuerte que la resistencia.'}],practicePrompt:'Count how many "just looking" responses you get today. Try the agree-and-pivot on each one. What percentage engage after the pivot?',practicePromptEs:'Cuenta cuántas respuestas de "solo miro" recibes hoy. Prueba el acuerdo-y-giro en cada una. ¿Qué porcentaje se engancha después del giro?',xpReward:20},{id:"dose-019",day:19,title:"The Budget Close",titleEs:"El Cierre de Presupuesto",category:"Closing",content:[{type:"mindset",text:"Budget is real. Respect it. But remember: people find money for things they VALUE. Your job: increase the perceived value until it exceeds the price.",textEs:"El presupuesto es real. respétalo. Pero recuerda: la gente encuentra dinero para cosas que VALORAN. Tu trabajo: aumentar el valor percibido hasta que supere el precio.",highlight:"Value perception > Price point. Always.",highlightEs:"Percepción de valor > Punto de precio. Siempre."},{type:"script",text:`"I totally get budgets. Let me ask you this: how much do you spend on skincare in a year? {currency}200? {currency}300? This one product replaces three others. So you're actually SAVING money while getting better results."`,textEs:'"Entiendo totalmente los presupuestos. Déjame preguntarte: ¿cuánto gastas en cuidado de la piel al año? ¿{currency}200? ¿{currency}300? Este producto reemplaza a otros tres. Así que en realidad estás AHORRANDO dinero mientras obtienes mejores resultados."'},{type:"technique",text:"The REPLACEMENT MATH: Show how your product replaces multiple products they already buy. 1 product = 3 replaced = net savings.",textEs:"La MATEMÁTICA DE REEMPLAZO: Muestra cómo tu producto reemplaza múltiples productos que ya compran. 1 producto = 3 reemplazados = ahorro neto."}],practicePrompt:'Use the replacement math on 3 budget-objection clients today. Track if reframing as "savings" changes the outcome.',practicePromptEs:'Usa la matemática de reemplazo en 3 clientes con objeción de presupuesto hoy. Registra si reformular como "ahorro" cambia el resultado.',xpReward:20},{id:"dose-020",day:20,title:"Create Urgency Without Pressure",titleEs:"Crear Urgencia Sin Presión",category:"Closing",content:[{type:"technique",text:"Urgency works, but only when it's REAL. Fake urgency destroys trust. Use genuine scarcity: limited stock, today's promotion, the gift that runs out.",textEs:"La urgencia funciona, pero solo cuando es REAL. La urgencia falsa destruye la confianza. Usa escasez genuina: stock limitado, promoción de hoy, el regalo que se acaba.",highlight:"Real urgency creates action. Fake urgency creates distrust.",highlightEs:"La urgencia real crea acción. La urgencia falsa crea desconfianza."},{type:"script",text:`"Just so you know — today we have a gift with purchase while supplies last. It's the Dead Sea Body Scrub, and we only have about 10 left. I don't want you to miss out!"`,textEs:'"Para que sepas — hoy tenemos un regalo con compra mientras duren las existencias. Es el Exfoliante del Mar Muerto, y solo nos quedan unos 10. ¡No quiero que te lo pierdas!"'},{type:"tip",text:`NEVER say "today only" if it's not true. Your credibility is everything. Instead, say "while supplies last" or "this week's promotion" — honest and effective.`,textEs:'NUNCA digas "solo hoy" si no es verdad. Tu credibilidad es todo. En su lugar, di "mientras duren las existencias" o "la promoción de esta semana" — honesto y efectivo.'}],practicePrompt:"Use genuine scarcity in your close today. Be specific about what's limited. Track your close rate vs. non-urgency closes.",practicePromptEs:"Usa escasez genuina en tu cierre hoy. Sé específica sobre qué es limitado. Registra tu tasa de cierre vs. cierres sin urgencia.",xpReward:20},{id:"dose-021",day:21,title:"The Voucher Close",titleEs:"El Cierre de Vale",category:"Closing",content:[{type:"technique",text:"The voucher close is your safety net. When nothing else works, the voucher gives them a reason to decide NOW. But use it as a final step, not your opening move.",textEs:"El cierre de vale es tu red de seguridad. Cuando nada más funciona, el vale les da una razón para decidir AHORA. Pero úsalo como paso final, no como movimiento de apertura.",highlight:"Save the voucher for the final push. Don't lead with it.",highlightEs:"Guarda el vale para el empujón final. No empieces con él."},{type:"script",text:`"Tell you what — I really want you to try this. I'm going to use my one voucher on you, today only. That takes it from {currency}175 down to {currency}140. That's my absolute best offer, and it's only because I know you'll love it."`,textEs:'"Mira — de verdad quiero que lo pruebes. Voy a usar mi único cupón contigo, solo por hoy. Eso lo baja de {currency}175 a {currency}140. Es mi mejor oferta absoluta, y es solo porque sé que te va a encantar."'},{type:"tip",text:`Personalise the voucher. "I'm going to give YOU..." makes it feel special. "We have a discount" makes it feel cheap and common.`,textEs:'Personaliza el vale. "Te voy a dar A TI..." lo hace sentir especial. "Tenemos un descuento" lo hace sentir barato y común.'}],practicePrompt:'Use the voucher close on 2 hesitant clients today. Track: did the personalised approach ("for you") feel different than generic discounts?',practicePromptEs:'Usa el cierre de vale en 2 clientes indecisos hoy. Registra: ¿el enfoque personalizado ("para ti") se sintió diferente que los descuentos genéricos?',xpReward:20},{id:"dose-022",day:22,title:"The Couples Approach",titleEs:"El Acercamiento a Parejas",category:"Advanced",content:[{type:"technique",text:"Approaching couples? ALWAYS engage the WOMAN first. Make eye contact with her, compliment her. The man is an observer, not the target. Win her, and he follows.",textEs:"¿Acercándote a parejas? SIEMPRE engancha a la MUJER primero. Haz contacto visual con ella, cumplímentala. El hombre es un observador, no el objetivo. Gánala a ella, y él sigue.",highlight:"Engage the woman. The man will follow her lead.",highlightEs:"Engancha a la mujer. El hombre seguirá su ejemplo."},{type:"script",text:`"Hi there! I have to say — your partner is very lucky to be with someone who takes such good care of their skin. I'm [Name], and I'm showcasing Swiss skincare today. Can I show you both something really cool?"`,textEs:'"¡Hola! Tengo que decir — tu pareja es muy afortunada de estar con alguien que cuida tanto su piel. Soy [Nombre], y estoy presentando cuidado de piel suizo hoy. ¿Puedo mostrarles algo muy genial?"'},{type:"tip",text:`If the man seems impatient, include him with a quick line: "This takes 30 seconds, and I think she'll love it." Most men will wait 30 seconds for their partner.`,textEs:'Si el hombre parece impaciente, inclúyelo con una línea rápida: "Esto toma 30 segundos, y creo que a ella le encantará." La mayoría de los hombres esperarán 30 segundos por su pareja.'}],practicePrompt:"Approach 3 couples today. Always start with the woman. Track: does the man wait, walk away, or engage? What patterns do you see?",practicePromptEs:"Acércate a 3 parejas hoy. Siempre empieza con la mujer. Registra: ¿el hombre espera, se va, o se engancha? ¿Qué patrones ves?",xpReward:25},{id:"dose-023",day:23,title:"Selling to Men",titleEs:"Vendiendo a Hombres",category:"Advanced",content:[{type:"mindset",text:"Men buy differently than women. They want SPEED, EFFICIENCY, and RESULTS. No fluff. No long demos. Get to the point. Show the product, show the result, name the price.",textEs:"Los hombres compran diferente que las mujeres. Quieren VELOCIDAD, EFICIENCIA, y RESULTADOS. Sin relleno. Sin demos largas. Ve al grano. Muestra el producto, muestra el resultado, di el precio.",highlight:"Men want the headline, not the whole article.",highlightEs:"Los hombres quieren el titular, no todo el artículo."},{type:"script",text:`"Sir, 30 seconds. This Scrub removes dead skin in one use. Your hands will feel smoother than they have in years. It's {currency}60, or {currency}60 for two if you take a Body Butter with it. Want to try it?"`,textEs:'"Señor, 30 segundos. Este Scrub quita la piel muerta en un solo uso. Tus manos van a quedar más suaves que en años. Son {currency}60, o {currency}60 por dos si te llevas un Body Butter también. ¿Lo pruebas?"'},{type:"tip",text:'The MAGIC WORD for men: "easy." Men love things that are easy. "Easy to use." "Easy application." "5 minutes, done." Use the E-word.',textEs:'La PALABRA MÁGICA para hombres: "fácil." Los hombres aman las cosas fáciles. "Fácil de usar." "Aplicación fácil." "5 minutos, listo." Usa la palabra E.'}],practicePrompt:"Approach 2 men today using the fast, direct method. Keep it under 60 seconds. Track your success rate.",practicePromptEs:"Acércate a 2 hombres hoy usando el método rápido y directo. Manténlo bajo 60 segundos. Registra tu tasa de éxito.",xpReward:25},{id:"dose-024",day:24,title:"Group Stopping Power",titleEs:"Poder de Parada en Grupo",category:"Advanced",content:[{type:"technique",text:"Groups are gold mines. Stop ONE person, and the rest stop too. Pick the most confident-looking person — they're the leader. Win the leader, win the group.",textEs:"Los grupos son minas de oro. Detén a UNA persona, y el resto también se detiene. Elige a la que luce más segura — esa es la líder. Gana a la líder, gana al grupo.",highlight:"Stop the leader. The group follows.",highlightEs:"Detén a la líder. El grupo sigue."},{type:"script",text:`"Hi ladies! I have to stop you — I just need ONE of you to try this, but I bet you'll ALL want one after you see it. Who's the bravest?"`,textEs:'"¡Hola chicas! Tengo que detenerlas — solo necesito que UNA lo pruebe, pero apuesto a que TODAS querrán uno después de verlo. ¿Quién es la más valiente?"'},{type:"tip",text:'Create SOCIAL PROOF within the group. When one person buys, announce it: "First one down, two to go!" Group dynamics create FOMO.',textEs:'Crea PRUEBA SOCIAL dentro del grupo. Cuando una compre, anúncialo: "¡Primera lista, faltan dos!" La dinámica de grupo crea FOMO.'}],practicePrompt:"Approach 1 group of 3+ people today. Use the leader technique. Track how many in the group engage vs. your solo approaches.",practicePromptEs:"Acércate a 1 grupo de 3+ personas hoy. Usa la técnica de la líder. Registra cuántas en el grupo se enganchan vs. tus acercamientos individuales.",xpReward:25},{id:"dose-025",day:25,title:"Body Language Mastery",titleEs:"Dominio del Lenguaje Corporal",category:"Advanced",content:[{type:"technique",text:"Master readers of body language outsell everyone. Learn the signals: Leaning in = interested. Crossed arms = guarded. Touching face = considering. Stepping back = objections coming.",textEs:"Los maestros en leer lenguaje corporal venden más que todos. Aprende las señales: Inclinarse = interesada. Brazos cruzados = a la defensiva. Tocarse la cara = considerando. Retroceder = objeciones vienen.",highlight:"Read their body before they speak.",highlightEs:"Lee su cuerpo antes de que hablen."},{type:"tip",text:"MIRROR their body language subtly. If they lean in, you lean in. If they speak softly, lower your voice. Mirroring builds unconscious rapport.",textEs:"REFLEJA su lenguaje corporal sutilmente. Si se inclinan, tú te inclinas. Si hablan bajo, baja tu voz. El reflejo construye rapport inconsciente."},{type:"technique",text:"The STEP-BACK TEST: If you lean back slightly and they lean forward to follow, they're hooked. If they also lean back, you're losing them. Adjust immediately.",textEs:"La PRUEBA DE RETROCESO: Si te inclinas hacia atrás ligeramente y ellos se inclinan hacia adelante para seguir, están enganchados. Si también se inclinan hacia atrás, los estás perdiendo. Ajusta inmediatamente."}],practicePrompt:"Today, focus ONLY on body language. Don't listen to words — watch movements. Note 5 body language signals you observe and what they meant.",practicePromptEs:"Hoy, enfócate SOLO en el lenguaje corporal. No escuches las palabras — observa los movimientos. Anota 5 señales de lenguaje corporal que observes y qué significaban.",xpReward:25},{id:"dose-026",day:26,title:"Spotting Buying Signals",titleEs:"Detectando Señales de Compra",category:"Advanced",content:[{type:"technique",text:`Buying signals are subtle but unmistakable once you know them. The question "How much is it?" is a BUYING signal, not an objection. They're already imagining owning it.`,textEs:'Las señales de compra son sutiles pero inconfundibles una vez que las conoces. La pregunta "¿Cuánto cuesta?" es una señal de COMPRA, no una objeción. Ya se la están imaginando.',highlight:'"How much?" means "I want it." Close immediately.',highlightEs:'"¿Cuánto?" significa "Lo quiero." Cierra inmediatamente.'},{type:"tip",text:'Other buying signals: asking about ingredients, checking the box, reading the label, asking "Do you take card?", saying "My sister would love this too."',textEs:'Otras señales de compra: preguntar por ingredientes, revisar la caja, leer la etiqueta, preguntar "¿Aceptan tarjeta?", decir "A mi hermana también le encantaría esto."'},{type:"script",text:'When you hear a buying signal, STOP TALKING. Transition immediately to the close: "Shall I wrap this up for you?" or "Would you like the gift bag with that?"',textEs:'Cuando escuches una señal de compra, DEJA DE HABLAR. Transiciona inmediatamente al cierre: "¿Te lo envuelvo?" o "¿Quieres la bolsa de regalo con eso?"'}],practicePrompt:"Count buying signals you spot today. For each one, close immediately. Track your close rate on buying-signal responses vs. regular closes.",practicePromptEs:"Cuenta las señales de compra que detectes hoy. Por cada una, cierra inmediatamente. Registra tu tasa de cierre en respuestas con señal de compra vs. cierres normales.",xpReward:25},{id:"dose-027",day:27,title:"The Silent Close",titleEs:"El Cierre en Silencio",category:"Advanced",content:[{type:"technique",text:"The most powerful close is SILENCE. After you present the offer, STOP TALKING. The first person to speak loses. Most salespeople talk themselves OUT of sales. Don't.",textEs:"El cierre más poderoso es el SILENCIO. Después de presentar la oferta, DEJA DE HABLAR. La primera persona en hablar pierde. La mayoría de los vendedores hablan para PERDER ventas. No lo hagas.",highlight:"Silence is a closing tool. Use it.",highlightEs:"El silencio es una herramienta de cierre. Úsala."},{type:"script",text:`After presenting the combo: "So — the full set is {currency}120. That's the Scrub, the Body Butter, and the Nail Kit goes in free." [STOP. SMILE. WAIT.]`,textEs:'Después de presentar el combo: "Entonces — el set completo son {currency}120. Es el Scrub, el Body Butter, y el Kit de Uñas entra gratis." [PARA. SONRÍE. ESPERA.]'},{type:"mindset",text:"Silence feels uncomfortable — FOR YOU. But for the customer, it's thinking time. They're weighing the decision. Every word you add after the close weakens your position.",textEs:"El silencio se siente incómodo — PARA TI. Pero para el cliente, es tiempo de pensar. Están sopesando la decisión. Cada palabra que agregues después del cierre debilita tu posición."}],practicePrompt:"Practice the silent close 3 times today. After stating the price and offer, count to 10 silently. Note what happens in the silence.",practicePromptEs:"Practica el cierre en silencio 3 veces hoy. Después de decir el precio y oferta, cuenta hasta 10 en silencio. Nota qué pasa en el silencio.",xpReward:25},{id:"dose-028",day:28,title:"The Callback Strategy",titleEs:"La Estrategia de Retorno",category:"Advanced",content:[{type:"technique",text:'Not everyone buys today. But a "no today" can become a "yes tomorrow." The callback strategy turns maybes into sales. Always leave the door open.',textEs:'No todos compran hoy. Pero un "no hoy" puede convertirse en "sí mañana." La estrategia de retorno convierte los tal vez en ventas. Siempre deja la puerta abierta.',highlight:'A "maybe" is a seed. Water it.',highlightEs:'Un "tal vez" es una semilla. Ríégala.'},{type:"script",text:`"No problem at all! I know it's a decision. Here's my card — I'm here every day until 6 PM. Come back and ask for me, I'll make sure you get the same gift I offered today. And I'll save you a sample to try!"`,textEs:'"¡Ningún problema! Sé que es una decisión. Aquí está mi tarjeta — estoy aquí todos los días hasta las 6 PM. Vuelve y pide por mí, me aseguraré de que obtengas el mismo regalo que ofrecí hoy. ¡Y te guardaré una muestra para probar!"'},{type:"tip",text:"ALWAYS give a reason to return: a saved sample, a reserved gift, a personal promise. Callbacks are warmer than cold stops. A returning customer has already decided — they just need permission.",textEs:"SIEMPRE da una razón para volver: una muestra guardada, un regalo reservado, una promesa personal. Los retornos son más cálidos que las paradas en frío. Un cliente que regresa ya decidió — solo necesita permiso."}],practicePrompt:`When someone says "I'll come back" today, use the callback strategy. Give them a specific reason to return. Track how many actually come back.`,practicePromptEs:'Cuando alguien diga "volveré" hoy, usa la estrategia de retorno. Dales una razón específica para regresar. Registra cuántos realmente vuelven.',xpReward:25},{id:"dose-029",day:29,title:"The 5-Minute Morning Routine",titleEs:"La Rutina Matutina de 5 Minutos",category:"Mindset",content:[{type:"mindset",text:"Champions don't wing it. The best salespeople in the world have a pre-shift routine. 5 minutes is all it takes to transform your entire day.",textEs:"Los campeones no improvisan. Los mejores vendedores del mundo tienen una rutina pre-turno. 5 minutos es todo lo que necesitas para transformar todo tu día.",highlight:"5 minutes of prep beats 8 hours of winging it.",highlightEs:"5 minutos de preparación superan 8 horas de improvisación."},{type:"technique",text:"THE POWER 5: (1) One deep breath. (2) One positive affirmation. (3) One goal for today. (4) One person you'll make smile. (5) One reason you're grateful to be here.",textEs:"EL PODER 5: (1) Una respiración profunda. (2) Una afirmación positiva. (3) Una meta para hoy. (4) Una persona que harás sonreír. (5) Una razón por la que estás agradecida de estar aquí."},{type:"tip",text:"Write your affirmation on your phone's lock screen. Every time you check your phone, you see it. Repetition creates belief.",textEs:"Escribe tu afirmación en la pantalla de bloqueo de tu teléfono. Cada vez que revises tu teléfono, la verás. La repetición crea creencia."}],practicePrompt:"Do the Power 5 every morning this week. Pick your affirmation now and set it as your lock screen. How does it feel after 3 days?",practicePromptEs:"Haz el Poder 5 cada mañana esta semana. Elige tu afirmación ahora y ponla como pantalla de bloqueo. ¿Cómo te sientes después de 3 días?",xpReward:30},{id:"dose-030",day:30,title:"Managing Your Energy",titleEs:"Gestionando Tu Energía",category:"Mindset",content:[{type:"mindset",text:"Sales is an energy game. You can't be at 100% all day — and that's okay. The pros know how to manage their energy like a battery: sprint, recharge, sprint again.",textEs:"Las ventas son un juego de energía. No puedes estar al 100% todo el día — y eso está bien. Los profesionales saben gestionar su energía como una batería: sprint, recarga, sprint de nuevo.",highlight:"Energy management > Time management.",highlightEs:"Gestión de energía > Gestión de tiempo."},{type:"technique",text:"THE 90-MINUTE RULE: Work in focused 90-minute blocks. Then take a 10-minute break. Walk, hydrate, breathe. You'll outperform someone who works nonstop for 8 hours.",textEs:"LA REGLA DE 90 MINUTOS: Trabaja en bloques enfocados de 90 minutos. Luego toma un descanso de 10 minutos. Camina, hidrátate, respira. Superarás a alguien que trabaja sin parar 8 horas."},{type:"tip",text:"HYDRATION = ENERGY. Dehydration feels like fatigue. Drink water every hour. Keep a bottle visible. Your energy, mood, and voice all improve when you're hydrated.",textEs:"HIDRATACIÓN = ENERGÍA. La deshidratación se siente como fatiga. Bebe agua cada hora. Mantén una botella visible. Tu energía, estado de ánimo y voz mejoran cuando estás hidratada."}],practicePrompt:"Try the 90-minute rule today. Set a timer. Work hard for 90 minutes, then take a real 10-minute break. Compare your results vs. a nonstop day.",practicePromptEs:"Prueba la regla de 90 minutos hoy. Pon un temporizador. Trabaja duro 90 minutos, luego toma un descanso real de 10 minutos. Compara tus resultados vs. un día sin parar.",xpReward:30},{id:"dose-031",day:31,title:"Goal Setting That Works",titleEs:"Metas Que Funcionan",category:"Mindset",content:[{type:"mindset",text:'"Sell more" is not a goal. "Make 30 stops today, bring 10 inside, close 3 sales" is a goal. Specific, measurable, actionable. Write it down. Say it out loud.',textEs:'"Vender más" no es una meta. "Hacer 30 paradas hoy, traer 10 adentro, cerrar 3 ventas" es una meta. Específica, medible, accionable. Escríbela. Dila en voz alta.',highlight:"Specific goals create specific results.",highlightEs:"Metas específicas crean resultados específicos."},{type:"technique",text:"THE DAILY 3: Every morning, write down 3 things: (1) Stops goal. (2) Inside goal. (3) Sales goal. Review at end of day. Adjust tomorrow based on today.",textEs:"EL DIARIO 3: Cada mañana, escribe 3 cosas: (1) Meta de paradas. (2) Meta de adentro. (3) Meta de ventas. Revisa al final del día. Ajusta mañana basándote en hoy."},{type:"mindset",text:"Your goals are a promise to yourself. Keep that promise. Every day you hit your goals, you build the identity of someone who follows through. That identity is your superpower.",textEs:"Tus metas son una promesa a ti misma. Mantén esa promesa. Cada día que cumples tus metas, construyes la identidad de alguien que cumple. Esa identidad es tu superpoder."}],practicePrompt:"Write your Daily 3 right now. Put it somewhere you'll see all day. At end of shift, score yourself 1-3 on each. What will you adjust tomorrow?",practicePromptEs:"Escribe tu Diario 3 ahora mismo. Ponlo donde lo verás todo el día. Al final del turno, califícate del 1-3 en cada uno. ¿Qué ajustarás mañana?",xpReward:30}],j=[{id:"ft-1",label:"Energy First — Bring the fire on every approach",labelEs:"Energía Primera — Trae el fuego en cada acercamiento"},{id:"ft-2",label:"Specific Compliments Only — Details stop people",labelEs:"Cumplidos Específicos — Los detalles detienen a la gente"},{id:"ft-3",label:"Silent Close — State the offer, then say nothing",labelEs:"Cierre en Silencio — Di la oferta, luego no digas nada"},{id:"ft-4",label:"Cost-Per-Day Reframe — Make price feel tiny",labelEs:"Reframe de Costo por Día — Haz que el precio se sienta pequeño"},{id:"ft-5",label:"Agree-and-Pivot — Turn objections into engagement",labelEs:"Acuerdo-y-Giro — Convierte objeciones en engagement"}];function D(){const t=(new Date().getDate()-1)%m.length;return m[t]}export{j as f,D as g,L as u};
